 function defaults(c:Collection){const o=['projects','tasks','contents','issues'].includes(c)?projectOwnerOptions()[0]?.value||'':data?.team[0]?.id||'';const base:Item={owner:o,status:'',name:'',notes:''};switch(c){case'customers':return{...base,status:'Tiềm năng'};case'services':return{...base,price:0,duration:30,revisions:2,unit:'gói',active:true};case'deals':return{...base,stage:STAGES[0],value:0,closeDate:today(),probability:10,description:''};case'projects':return{...base,status:'Đang triển khai',budget:0,cost:0,revisions:2,startDate:today(),dueDate:today()};case'tasks':return{...base,status:'Cần làm',dueDate:today(),hours:0,hourlyCost:0};case'contents':return{...base,status:'Ý tưởng',channel:'Facebook',version:1,publishDate:today(),url:'',body:'',feedback:''};case'changes':return{};case'issues':return{...base,status:'Đang mở',priority:'Trung bình',dueDate:today()};case'assets':return{...base,category:'Case study',shareable:false,watermark:false,url:''};case'team':return{name:'',email:'',role:'Account',color:'#ee683b'};}}
